# -*- coding: utf-8 -*-
import json, os, re

ROOT = r'D:/repository'
SEL  = r'C:/Users/Administrator/.dsh/cache/memory-audit/select.json'
OUT  = r'C:/Users/Administrator/.dsh/cache/memory-audit/evidence.txt'

SKIP_DIRS = {'.git','node_modules','dist','.idea','.vscode','__pycache__','.cache','coverage','.nuxt','build'}
EXTS = {'.vue','.js','.ts','.jsx','.tsx','.py','.css','.scss','.html','.json','.mjs','.cjs','.yml','.yaml'}

# 1) index all files by basename
idx = {}
textfiles = []
for dp, dns, fns in os.walk(ROOT):
    dns[:] = [d for d in dns if d not in SKIP_DIRS]
    for fn in fns:
        ext = os.path.splitext(fn)[1].lower()
        if ext in EXTS:
            full = os.path.join(dp, fn)
            idx.setdefault(fn, []).append(full)
            if ext in {'.vue','.js','.ts','.jsx','.tsx','.py','.css','.scss','.html','.mjs','.cjs'}:
                textfiles.append(full)

def read_text(p):
    try:
        with open(p, encoding='utf-8', errors='ignore') as f:
            return f.read()
    except Exception:
        return ''

d = json.load(open(SEL, encoding='utf-8'))
lines = []
lines.append(f"indexed_files={len(idx)} textfiles={len(textfiles)} total_memories={d['total_memories']} picked={d['picked']}\n")

for i, c in enumerate(d['candidates'], 1):
    content = c['content'].replace('\\\\n', '\n')
    # referenced filenames
    refs = set()
    for m in re.findall(r'[\w\u4e00-\u9fff./\\-]+\.(?:vue|js|ts|jsx|tsx|py|css|scss|html|json|mjs)', content):
        refs.add(os.path.basename(m.replace('\\','/')))
    # backticked identifiers (ascii) length>=4
    syms = set()
    for t in re.findall(r'`([^`]+)`', content):
        for s in re.findall(r'[A-Za-z_][A-Za-z0-9_]{3,}', t):
            syms.add(s)
    # find matched files (basename)
    matched_files = []
    for r in refs:
        if r in idx:
            matched_files.extend(idx[r][:3])
    matched_files = list(dict.fromkeys(matched_files))[:12]
    # search symbols inside matched files, else globally (limited)
    search_pool = matched_files if matched_files else textfiles
    sym_hits = {}
    for s in sorted(syms):
        hits = 0
        hitfile = ''
        for p in search_pool:
            txt = read_text(p)
            if s in txt:
                hits += 1
                if not hitfile:
                    hitfile = os.path.relpath(p, ROOT)
                if hits >= 3:
                    break
        sym_hits[s] = (hits, hitfile)

    lines.append('='*8 + f" #{i} {c['uri'].split('/')[-1]} sha={c['body_sha256_16']} " + '='*8)
    lines.append('--CONTENT--')
    lines.append(content)
    lines.append('--EVIDENCE--')
    if matched_files:
        for p in matched_files:
            lines.append('FILE ' + os.path.relpath(p, ROOT))
    else:
        lines.append('FILE (none of the referenced basenames exist in index)')
    for s,(h,hf) in sym_hits.items():
        lines.append(f"SYM {s} hits={h} {hf}")
    lines.append('')

open(OUT,'w',encoding='utf-8').write('\n'.join(lines))
print('wrote', OUT, 'lines', len(lines))

