# -*- coding: utf-8 -*-
import json, os, re

ROOT = r'D:/repository'
SEL  = r'C:/Users/Administrator/.dsh/cache/memory-audit/select.json'
OUT  = r'C:/Users/Administrator/.dsh/cache/memory-audit/matrix.txt'

SKIP = {'.git','node_modules','dist','.idea','.vscode','__pycache__','.cache','coverage','.nuxt','build','.DS_Store'}
EXTS = {'.vue','.js','.ts','.jsx','.tsx','.py','.css','.scss','.html','.mjs','.cjs'}

d = json.load(open(SEL, encoding='utf-8'))

# collect claimed symbols per memory
claims = []
for c in d['candidates']:
    content = c['content'].replace('\\\\n','\n')
    syms = set()
    for t in re.findall(r'`([^`]+)`', content):
        for s in re.findall(r'[A-Za-z_][A-Za-z0-9_]{4,}', t):
            syms.add(s)
    # also explicit function-ish tokens in prose
    for s in re.findall(r'\b(?:getDetail|showCandidateTable|goEmptyFiling|listAppendixPackage|resolvedBusId|receiptVerifyFilter|start=None|bizState|document_type|pickSelectOption)\b', content):
        syms.add(s)
    claims.append(syms)

allsyms = set().union(*claims)

# one scan of all text files: count interesting tokens, track sample file
count = {s:0 for s in allsyms}
sample = {s:'' for s in allsyms}
nfiles=0
for dp, dns, fns in os.walk(ROOT):
    dns[:] = [x for x in dns if x not in SKIP]
    for fn in fns:
        if os.path.splitext(fn)[1].lower() not in EXTS: continue
        p = os.path.join(dp, fn)
        try:
            with open(p, encoding='utf-8', errors='ignore') as f: txt=f.read()
        except Exception: continue
        nfiles+=1
        for s in allsyms:
            if s in txt:
                count[s]+=1
                if not sample[s]: sample[s]=os.path.relpath(p, ROOT)

lines=[f'scanned_files={nfiles} symbols={len(allsyms)}']
for i,(c,syms) in enumerate(zip(d['candidates'],claims),1):
    lines.append('='*6+f" #{i} {c['uri'].split('/')[-1]} sha={c['body_sha256_16']} "+"='*6")
    for s in sorted(syms):
        lines.append(f"  {s}: {count[s]}  {sample[s]}")
open(OUT,'w',encoding='utf-8').write('\n'.join(lines))
print('wrote',OUT,'scanned',nfiles,'lines',len(lines))

# -*- coding: utf-8 -*-
import json, os, re
ROOT=r'D:/repository'
SEL=r'C:/Users/Administrator/.dsh/cache/memory-audit/select.json'
OUT=r'C:/Users/Administrator/.dsh/cache/memory-audit/targeted.txt'
SKIP={'.git','node_modules','dist','dist-mp-weixin','.idea','.vscode','__pycache__','.cache','coverage','.nuxt','build','report.html'}
EXTS={'.vue','.js','.ts','.jsx','.tsx','.py','.css','.scss','.html','.mjs','.cjs'}
GENERIC={'变更内容','涉及文件','所属项目','验证证据','修改说明','效果','问题背景','修复方案','解决方案','注意事项','操作步骤','缓存与复报','实现','验证与归属','来源会话','代码基线','背景','修复口径','归一化兼容','查看态回退','仓库与部署','关键组件与归属','并行任务隔离','问题原因','处理步骤','验证'}

d=json.load(open(SEL,encoding='utf-8'))

# build path list once
allpaths=[]
alltext=[]
for dp,dns,fns in os.walk(ROOT):
    dns[:]=[x for x in dns if x not in SKIP]
    for fn in fns:
        ext=os.path.splitext(fn)[1].lower()
        if ext not in EXTS: continue
        p=os.path.join(dp,fn)
        rel=os.path.relpath(p,ROOT).replace('\\','/')
        allpaths.append(rel)
        if ext in {'.vue','.js','.ts','.jsx','.tsx','.py','.css','.scss','.html','.mjs','.cjs'}:
            try: alltext.append((rel,open(p,encoding='utf-8',errors='ignore').read()))
            except Exception: pass

def find_file(ref):
    ref=ref.replace('\\','/').lstrip('./')
    hits=[p for p in allpaths if p.endswith('/'+ref) or p==ref]
    return hits

lines=[f'files={len(allpaths)} texts={len(alltext)}']
for i,c in enumerate(d['candidates'],1):
    content=c['content'].replace('\\\\n','\n')
    lines.append('='*5+f" #{i} {c['uri'].split('/')[-1]} sha={c['body_sha256_16']} "+"='*5")
    # severity: project / files claim
    m=re.search(r'所属项目[：:]\s*([^\n；;]+)',content)
    if m: lines.append('  PROJ '+m.group(1).strip())
    # referenced file paths
    paths=set()
    for mm in re.findall(r'[\w\u4e00-\u9fff./\\-]+\.(?:vue|js|ts|jsx|tsx|py|css|scss|html|mjs)',content):
        if '/' in mm or '\\' in mm: paths.add(mm)
    found=0; miss=[]
    for r in sorted(paths):
        h=find_file(r)
        if h: found+=1
        else: miss.append(r)
    lines.append(f'  FILEPATHS ref={len(paths)} found={found} miss={len(miss)}')
    for r in miss[:6]: lines.append('    MISS '+r)
    # distinctive tokens: ascii identifiers len>=5 + chinese quoted phrases len>=3
    toks=set()
    for t in re.findall(r'`([^`]+)`',content):
        for s in re.findall(r'[A-Za-z_][A-Za-z0-9_]{4,}',t): toks.add(s)
    for s in re.findall(r'[A-Za-z_][A-Za-z0-9_]{6,}',content): toks.add(s)
    for s in re.findall(r'「([^」]{3,12})」',content):
        if s not in GENERIC: toks.add(s)
    rare=[]; absent=[]
    for s in sorted(toks):
        cnt=0; samp=''
        for rel,txt in alltext:
            if s in txt:
                cnt+=1
                if not samp: samp=rel
                if cnt>40: break
        if cnt==0: absent.append(s)
        elif cnt<=40: rare.append(f'{s}({cnt})')
    lines.append('  RARE '+' '.join(rare))
    lines.append('  ABSENT '+' '.join(absent))
open(OUT,'w',encoding='utf-8').write('\n'.join(lines))
print('wrote',OUT,'lines',len(lines))

